from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the full-width or full-height divider.
    divider = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            divider = ("row", r)
            break
    if divider is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                divider = ("col", c)
                break

    if divider[0] == "row":
        _, r = divider
        first, second = grid[:r], grid[r + 1:]
    else:
        _, c = divider
        first = [row[:c] for row in grid]
        second = [row[c + 1:] for row in grid]

    background = Counter(x for row in first for x in row).most_common(1)[0][0]
    return [
        [3 if first[i][j] == second[i][j] else background
         for j in range(len(first[0]))]
        for i in range(len(first))
    ]
