from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []

    for r, row in enumerate(grid):
        if len(set(row)) == 1 and 0 < r < h - 1:
            a, b = grid[:r], grid[r + 1:]
            if len(a) == len(b):
                candidates.append((0, r, a, b))

    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1 and 0 < c < w - 1:
            a = [row[:c] for row in grid]
            b = [row[c + 1:] for row in grid]
            if len(a[0]) == len(b[0]):
                candidates.append((1, c, a, b))

    _, _, a, b = candidates[0]
    counts_a = Counter(x for row in a for x in row)
    counts_b = Counter(x for row in b for x in row)
    common = set(counts_a) & set(counts_b)
    color = max(common, key=lambda x: min(counts_a[x], counts_b[x]))

    return [
        [3 if a[r][c] == color and b[r][c] == color else color
         for c in range(len(a[0]))]
        for r in range(len(a))
    ]
